mapper.select:
/* RTC 차량 상품화비용 목록 */
SELECT	V_CARCD
	,	V_COST_TYPE_CD
	,	V_COST_TYPE_SUB_CD
	,	N_COST_PRICE
	,	N_COST_PRICE * RTC_CAL_COST_ATTR(V_COST_TYPE_CD)	AS N_SIGNED_COST_PRICE
FROM	RTC_CAR_COST_MNG
WHERE	V_CARCD = #{carCd}

	AND V_COST_TYPE_CD = #{costTypeCd}


	AND V_COST_TYPE_SUB_CD = #{costTypeSubCd}

/* RTC_CAL_TOTAL_COST의 조건별 집계를 SQL에서 직접 사용하는 예시 */
SELECT	NVL(SUM(N_COST_PRICE * RTC_CAL_COST_ATTR(V_COST_TYPE_CD)), 0)
FROM	RTC_CAR_COST_MNG
WHERE	V_CARCD = #{carCd}

	AND V_COST_TYPE_CD = #{costTypeCd}


	AND V_COST_TYPE_SUB_CD = #{costTypeSubCd}
